#[cfg(all(test, target_os = "macos"))]
mod static_font_tests {
    use std::sync::Arc;

    use font_kit::{
        font::Font,
        matching::find_best_match,
        properties::{Properties, Style, Weight},
    };

    use super::{INTER_FONTS, JETBRAINS_MONO_FONTS};
    use crate::app_settings::TerminalFontFamily;

    #[test]
    fn jetbrains_mono_static_faces_resolve_under_the_settings_family_name() {
        let faces = JETBRAINS_MONO_FONTS
            .iter()
            .map(|bytes| {
                Font::from_bytes(Arc::new(bytes.to_vec()), 0).expect("valid JetBrains Mono face")
            })
            .collect::<Vec<_>>();
        assert_eq!(
            faces.iter().map(Font::family_name).collect::<Vec<_>>(),
            vec![TerminalFontFamily::JetBrainsMono.family(); 4]
        );
        // The UI monospace request must name the bundled family exactly, or
        // gpui silently resolves it to its own fallback stack (Helvetica on
        // macOS) with no log line.
        assert_eq!(
            runner_app::platform_fonts::UI_MONOSPACE_FONT,
            TerminalFontFamily::JetBrainsMono.family()
        );
        assert_eq!(
            faces
                .iter()
                .map(|face| {
                    let properties = face.properties();
                    (properties.weight, properties.style)
                })
                .collect::<Vec<_>>(),
            vec![
                (Weight::NORMAL, Style::Normal),
                (Weight::NORMAL, Style::Italic),
                (Weight::BOLD, Style::Normal),
                (Weight::BOLD, Style::Italic),
            ]
        );
    }

    #[test]
    fn inter_static_faces_resolve_regular_and_semibold_separately() {
        let faces = INTER_FONTS
            .iter()
            .map(|bytes| Font::from_bytes(Arc::new(bytes.to_vec()), 0).expect("valid Inter face"))
            .collect::<Vec<_>>();
        assert!(faces.iter().all(|face| face.family_name() == "Inter"));

        let properties = faces.iter().map(Font::properties).collect::<Vec<_>>();
        assert_eq!(
            properties
                .iter()
                .map(|properties| (properties.weight, properties.style))
                .collect::<Vec<_>>(),
            vec![
                (Weight::NORMAL, Style::Normal),
                (Weight::NORMAL, Style::Italic),
                (Weight::MEDIUM, Style::Normal),
                (Weight::MEDIUM, Style::Italic),
                (Weight::SEMIBOLD, Style::Normal),
                (Weight::SEMIBOLD, Style::Italic),
                (Weight::BOLD, Style::Normal),
                (Weight::BOLD, Style::Italic),
            ]
        );
        let regular = find_best_match(&properties, &Properties::new()).expect("regular face");
        let semibold = find_best_match(
            &properties,
            &Properties {
                weight: Weight::SEMIBOLD,
                ..Properties::new()
            },
        )
        .expect("semibold face");

        assert_ne!(regular, semibold);
        assert_eq!(properties[regular].weight, Weight::NORMAL);
        assert_eq!(properties[semibold].weight, Weight::SEMIBOLD);
    }
}

pub struct Assets;

pub fn app_icon_source() -> ImageSource {
    ImageSource::Resource(Resource::Embedded("app-icon.png".into()))
}

impl AssetSource for Assets {
    fn load(&self, path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        Ok(ASSETS
            .iter()
            .find(|(asset_path, _)| *asset_path == path)
            .map(|(_, bytes)| Cow::Borrowed(*bytes)))
    }

    fn list(&self, path: &str) -> Result<Vec<SharedString>> {
        Ok(ASSETS
            .iter()
            .filter(|(asset_path, _)| asset_path.starts_with(path))
            .map(|(asset_path, _)| SharedString::from(*asset_path))
            .collect())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn app_icon_uses_the_embedded_asset_loader() {
        assert!(matches!(
            app_icon_source(),
            ImageSource::Resource(Resource::Embedded(path)) if path.as_ref() == "app-icon.png"
        ));
    }

    #[test]
    fn update_hint_icon_is_registered() {
        assert!(Assets.load("circle-arrow-down.svg").unwrap().is_some());
    }

    #[test]
    fn fork_icon_is_registered() {
        assert!(Assets.load("git-fork.svg").unwrap().is_some());
    }

    #[test]
    fn provider_marks_are_registered_as_single_path_masks() {
        for path in ["claude.svg", "openai.svg", "trae.svg", "copilot.svg"] {
            let bytes = Assets.load(path).unwrap().expect("bundled provider mark");
            let svg = std::str::from_utf8(&bytes).unwrap();
            assert!(svg.contains("viewBox=\"-2 -2 28 28\""));
            assert_eq!(svg.matches("<path ").count(), 1);
            if path == "openai.svg" {
                assert!(svg.contains("fill-rule=\"evenodd\""));
            }
        }
    }

    #[test]
    fn terminal_drawer_icons_are_registered() {
        assert!(Assets.load("panel-bottom-hidden.svg").unwrap().is_some());
        assert!(Assets.load("panel-bottom-open.svg").unwrap().is_some());
    }
}
